// Retrieve thread_ts - first from Authentik payload, then from workflow static data

const inputData = $input.first().json;
const email = inputData.body?.user?.email;

if (!email) {
  return [{ json: { threadTs: '', found: false, error: 'No email in payload', ...inputData } }];
}

// First, check if thread_ts was passed from Authentik (stored in user attributes)
const payloadThreadTs = inputData.body?.user?.slack_thread_ts;
if (payloadThreadTs) {
  return [{ json: { threadTs: payloadThreadTs, found: true, source: 'authentik', ...inputData } }];
}

// Fallback to workflow static data
const threads = $getWorkflowStaticData('global').threads || {};
const thread = threads[email];

if (thread && thread.ts) {
  return [{ json: { threadTs: thread.ts, found: true, source: 'static_data', ...inputData } }];
} else {
  // No thread found - will post as new message
  return [{ json: { threadTs: '', found: false, ...inputData } }];
}

// Store thread_ts in workflow static data

// Get webhook data from the Webhook node
const webhookItems = $('Webhook').all();
if (!webhookItems || webhookItems.length === 0) {
  throw new Error('No data from Webhook node');
}
const webhookData = webhookItems[0].json;

// User data is inside body.user
const email = webhookData.body?.user?.email;
if (!email) {
  console.log('Webhook data:', JSON.stringify(webhookData));
  throw new Error('No user.email in webhook data');
}

// Slack response - the Slack node returns the response in the current input
const slackResponse = $input.first().json;
const threadTs = slackResponse.message?.ts || slackResponse.ts || slackResponse.message_timestamp;

if (!threadTs) {
  console.log('Slack response:', JSON.stringify(slackResponse));
  throw new Error('No thread_ts found in Slack response');
}

// Get existing threads map or create new
let threads = $getWorkflowStaticData('global').threads || {};
threads[email] = {
  ts: threadTs,
  timestamp: Date.now()
};

// Clean old entries > 30 days
const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
threads = Object.fromEntries(
  Object.entries(threads).filter(([_, v]) => v.timestamp > thirtyDaysAgo)
);

// Store back
$getWorkflowStaticData('global').threads = threads;

return [{ json: { email, threadTs, success: true } }];

